settings.custom_liquid:
{%- comment -%}
Breadcrumb mit „Primärer Collection“:
Reihenfolge:
1) Context collection (wenn via /collections/.../products/... geöffnet)
2) Metafeld product.metafields.custom.primary_collection (Collection-Referenz)
3) Fallback: product.collections.first
{%- endcomment -%}

{%- assign context_col = collection -%}
{%- assign primary = product.metafields.custom.primary_collection -%}
{%- if context_col == nil and primary and primary.value -%}
  {%- assign context_col = primary.value -%}
{%- endif -%}
{%- if context_col == nil and product and product.collections and product.collections.size > 0 -%}
  {%- assign context_col = product.collections.first -%}
{%- endif -%}

<nav class="breadcrumb" role="navigation" aria-label="breadcrumbs">
  <a href="{{ routes.root_url }}">Startseite</a>

  {%- if template contains 'product' -%}
    {%- if context_col -%}
      <span aria-hidden="true">›</span>
      <a href="{{ context_col.url }}">{{ context_col.title }}</a>
    {%- endif -%}
    <span aria-hidden="true">›</span>
    <span>{{ product.title }}</span>

  {%- elsif template contains 'collection' and collection -%}
    <span aria-hidden="true">›</span>
    <span>{{ collection.title }}</span>

  {%- elsif template contains 'page' -%}
    <span aria-hidden="true">›</span>
    <span>{{ page.title }}</span>

  {%- elsif template contains 'blog' -%}
    <span aria-hidden="true">›</span>
    <span>{{ blog.title }}</span>

  {%- elsif template contains 'article' -%}
    <span aria-hidden="true">›</span>
    <a href="{{ blog.url }}">{{ blog.title }}</a>
    <span aria-hidden="true">›</span>
    <span>{{ article.title }}</span>
  {%- endif -%}
</nav>

<style>
  .breadcrumb {
    font-size: 0.75rem; /* noch kleiner */
    color: #666;
    margin-bottom: 0.75rem;
  }
  .breadcrumb a {
    color: #333;          /* neutral, nicht blau */
    text-decoration: none;
  }
  .breadcrumb a:hover {
    text-decoration: underline;
  }
  .breadcrumb span[aria-hidden="true"] {
    margin: 0 4px;
    color: #999;
  }
</style>

{%- assign current_variant = product.selected_or_first_available_variant -%}
<span class="sku-and-warranty">
  {{ current_variant.sku }} | 
  <a href="https://motionsports.de/pages/garantiebedingungen" target="_blank">Garantiebedingungen</a>
</span>

<style>
  .sku-and-warranty {
    font-size: 0.7rem;    /* ~1/3 kleiner als Standard */
    color: #333;          /* dezentes Grau */
  }

  .sku-and-warranty a {
    color: inherit;       /* übernimmt die Schriftfarbe */
    text-decoration: none;
  }

  .sku-and-warranty a:hover {
    text-decoration: underline;
  }
</style>

{% if product.metafields.custom.kurzinfo != blank %}
  <div class="product-kurzinfo">
    {{ product.metafields.custom.kurzinfo | metafield_tag }}
  </div>
{% endif %}

<style>
  /* === Block clean, Strich 100% === */
  .product-kurzinfo {
    margin: 0 0 20px 0 !important;       /* unten 20px Abstand */
    padding: 0 0 1rem 0 !important;      /* unten etwas Luft */
    text-align: left !important;
    display: block;
    width: 100%;
    box-sizing: border-box;
    position: relative;
    border-bottom: 1px solid #ccc;       /* Strich in voller Breite */
  }

  .product-kurzinfo * {
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
  }

  /* === UL & LI Reset === */
  .product-kurzinfo ul {
    margin: 0 !important;
    padding: 0 !important;
    list-style: none !important;
  }

  /* === LI mit feinem Häkchen === */
  .product-kurzinfo li {
    margin: 0 0 4px 0;
    padding-left: 1.5em;
    position: relative;
    text-align: left;
  }

  .product-kurzinfo li::before {
    content: "✓";
    color: #333;
    font-weight: normal;
    font-size: 0.9em;
    position: absolute;
    left: 0;
    top: 0.1em;
  }

  /* === Mobil: mehr Abstand zwischen Haken und Text === */
  @media (max-width: 600px) {
    .product-kurzinfo li {
      padding-left: 1.8em;
    }
  }

  /* === Extra-Regel für Sticky Sidebar === */
  .sticky-sidebar.product-info .metafield-rich_text_field {
    padding-bottom: 0px !important;
  }
</style>

{%- assign current_variant = product.selected_or_first_available_variant -%}
<div class="product-price">
  <span class="regular-price">
    {{ current_variant.price | money }}
  </span>
  <span class="price-vat-note">
    inkl. MwSt.
  </span>
</div>

<style>
  .product-price {
    display: flex;
    align-items: baseline; /* Preis und Hinweis auf einer Linie */
    gap: 6px;              /* kleiner Abstand zwischen Preis und MwSt */
    margin: 0 !important;  /* KEIN Außenabstand */
    padding: 0 !important; /* KEIN Innenabstand */
  }
  .product-price .regular-price {
    font-size: 2em;        /* doppelt so groß */
    font-weight: 600;      /* hervorgehoben */
    line-height: 1;
    margin: 0 !important;
    padding: 0 !important;
  }
  .product-price .price-vat-note {
    font-size: 0.75rem;    /* klein */
    color: #666;           /* dezenter Ton */
    margin: 0 !important;
    padding: 0 !important;
  }
</style>

{% if product.available %}
<style>
  @media screen and (max-width: 480px) {
    #targo-widget .de-hinweis {
      display: none !important;
    }
    #targo-widget .finanzieren-text::after {
      content: "";
    }
  }
</style>

<!-- Widget wird initial versteckt -->
<div id="targo-widget"
     style="display: none; flex; align-items: center; gap: 12px; margin-top: 10px; cursor: pointer;"
     onclick="document.getElementById('targo-popup').style.display='block'">

  <img src="https://cdn.shopify.com/s/files/1/0823/4896/6217/files/targobank-nopadding.png?v=1745487001"
       alt="Targobank Finanzierung"
       class="targo-logo"
       style="width: 120px; margin-top: -5px;" />

  <div style="display: flex; align-items: center; gap: 6px; flex-wrap: wrap;">
    <span id="finanzierungs-info"
          class="finanzieren-text"
          style="font-weight: bold; font-size: 13px; color: #333;"></span>

    <div style="position: relative; display: flex; align-items: center; gap: 6px;">
      <div style="position: relative; display: inline-block;">
        <span style="display: inline-flex; align-items: center; justify-content: center;
                     width: 15px; height: 15px; border-radius: 50%;
                     background-color: #fff; color: #000;
                     border: 1px solid #000;
                     font-size: 11px; font-weight: bold;">i</span>
        <div style="visibility: hidden; opacity: 0; background-color: #000; color: #fff;
                    text-align: center; padding: 5px 10px; border-radius: 6px;
                    position: absolute; z-index: 1; bottom: 125%; left: 50%; transform: translateX(-50%);
                    transition: opacity 0.3s; font-size: 12px; white-space: nowrap;">
          Flexible Finanzierung mit unserem Partner TARGOBANK
          <div style="position: absolute; top: 100%; left: 50%; margin-left: -5px;
                      border-width: 5px; border-style: solid; border-color: #000 transparent transparent transparent;"></div>
        </div>
      </div>

      <!-- Deutschlandflagge + Hinweis leicht tiefer -->
      <div style="display: flex; align-items: center; gap: 4px; margin-top: 1px;">
        <img src="https://cdn.shopify.com/s/files/1/0823/4896/6217/files/de.png?v=1746717546"
             alt="DE"
             style="width: 15px; height: 15px; border-radius: 50%; border: 1px solid #000;" />
        <span class="de-hinweis" style="font-size: 10px; color: #333;">(nur DE)</span>
      </div>
    </div>
  </div>
</div>

<!-- Lightbox -->
<div id="targo-popup" style="display:none; position: fixed; z-index: 9999; left: 0; top: 0; width: 100%; height: 100%; background-color: rgba(0,0,0,0.5);">
  <div style="background: white; width: 90%; max-width: 400px; margin: 10% auto; padding: 20px; border-radius: 8px; position: relative;">
    <span onclick="document.getElementById('targo-popup').style.display='none'"
          style="position: absolute; top: 10px; right: 15px; font-size: 20px; cursor: pointer;">&times;</span>

    <div style="display: flex; align-items: center; gap: 12px; margin-bottom: 15px;">
      <img src="https://cdn.shopify.com/s/files/1/0823/4896/6217/files/targobank-nopadding.png?v=1745487001"
           alt="Targobank Logo" style="width: 120px;" />
      <span style="font-weight: bold; font-size: 11px; color: #333;">Ratenkauf bis 36 Monate</span>
    </div>

    <h3><b>Erfülle Dir deinen Wunsch – ganz einfach finanzieren</b></h3>
    <p>Manche Träume möchten nicht warten. Gemeinsam mit unserem Finanzierungspartner, der TARGOBANK, ermöglichen wir dir eine einfache und bequeme Finanzierung ohne Anzahlung – für alle Warenkörbe ab 99,00 €, zu einem attraktiven Zinssatz.</p>

<h4 style="margin-top: 20px;"><b>Konditionen</b></h4>
<table style="width: 100%; border-collapse: collapse; font-size: 13px; margin-top: 10px; border: 1px solid #ccc;">
  <thead style="background-color: #f5f5f5;">
    <tr>
      <th style="padding: 10px; border: 1px solid #ccc; text-align: left;">Laufzeit</th>
      <th style="padding: 10px; border: 1px solid #ccc; text-align: left;">Nominalzins</th>
      <th style="padding: 10px; border: 1px solid #ccc; text-align: left;">Effektivzins</th>
    </tr>
  </thead>
  <tbody>
    <tr>
      <td style="padding: 10px; border: 1px solid #ccc;">6 Monate</td>
      <td style="padding: 10px; border: 1px solid #ccc;">4,90%</td>
      <td style="padding: 10px; border: 1px solid #ccc;">4,99%</td>
    </tr>
    <tr>
      <td style="padding: 10px; border: 1px solid #ccc;">12 Monate</td>
      <td style="padding: 10px; border: 1px solid #ccc;">5,86%</td>
      <td style="padding: 10px; border: 1px solid #ccc;">5,99%</td>
    </tr>
    <tr>
      <td style="padding: 10px; border: 1px solid #ccc;">18 Monate</td>
      <td style="padding: 10px; border: 1px solid #ccc;">6,82%</td>
      <td style="padding: 10px; border: 1px solid #ccc;">6,99%</td>
    </tr>
    <tr>
      <td style="padding: 10px; border: 1px solid #ccc;">24 Monate</td>
      <td style="padding: 10px; border: 1px solid #ccc;">7,77%</td>
      <td style="padding: 10px; border: 1px solid #ccc;">7,99%</td>
    </tr>
    <tr>
      <td style="padding: 10px; border: 1px solid #ccc;">36 Monate</td>
      <td style="padding: 10px; border: 1px solid #ccc;">8,71%</td>
      <td style="padding: 10px; border: 1px solid #ccc;">8,99%</td>
    </tr>
  </tbody>
</table>


    <h4 style="margin-top: 20px;"><b>Deine Vorteile</b></h4>
    <ul style="margin: 10px 0 0 20px; padding-left: 0; list-style-type: disc; font-size: 13px;">
      <li>Individuell: Laufzeit und Raten ganz nach deinen Bedürfnissen – schon ab €10 im Monat</li>
      <li>Einfach und schnell: in wenigen Minuten abgeschlossen</li>
      <li>Flexible Laufzeiten: zwischen 6 und 36 Monaten</li>
    </ul>
  </div>
</div>

<!-- JavaScript: Preisberechnung & Anzeige -->
<script>
  document.addEventListener("DOMContentLoaded", function () {
    var price = {{ product.price | money_without_currency | remove: '.' | replace: ',', '.' }};
    var compare = {{ product.compare_at_price | money_without_currency | default: '0' | remove: '.' | replace: ',', '.' }};
    price = Math.max(price, compare);

    var interestRate = 0.0871;
    var months = 36;
    var monthlyInterest = interestRate / 12;
    var monthlyPayment = price * monthlyInterest / (1 - Math.pow(1 + monthlyInterest, -months));

    var finanzierungsInfo = document.getElementById("finanzierungs-info");
    var infoText = "";

    if (monthlyPayment >= 10) {
      var formatted = monthlyPayment.toFixed(2).replace('.', ',');
      infoText = "ab " + formatted + " €/Monat";
    } else {
      infoText = "Ratenkauf bis 36 Monate";
    }

    finanzierungsInfo.innerHTML = "<strong>" + infoText + "</strong>";
    document.getElementById("targo-widget").style.display = "flex";

    const infoIcon = document.querySelector('div[style*="inline-block"] > span');
    const tooltip = infoIcon.nextElementSibling;

    infoIcon.addEventListener('mouseenter', () => {
      tooltip.style.visibility = 'visible';
      tooltip.style.opacity = '1';
    });
    infoIcon.addEventListener('mouseleave', () => {
      tooltip.style.visibility = 'hidden';
      tooltip.style.opacity = '0';
    });
  });
</script>
{% endif %}
